// Official medical-tourism registries, published as browsable directories under
// /destinations/[destination]/directory. These pages state ONE fact per row: the
// facility appears on the government list named in `meta.source` as of
// `meta.asOf`. No judgement, no ranking. The hand-researched ClinicProfiles in
// the dossiers are a small subset; `profiledRowIds` links the two layers.
//
// Data files are generated by scripts/registries/build-*.py from the official
// sources and must not be edited by hand. Re-run the scripts to refresh.

import turkey from '@/data/registries/turkey.json';
import korea from '@/data/registries/south-korea.json';
import mexico from '@/data/registries/mexico.json';
import { DOSSIERS } from '@/lib/destinations/dossiers';

export interface RegistryRow {
  id: string;
  name: string;
  region: string;
  regionSlug: string;
  district: string;
  category: string;
  typeLabel: string;
  typeOriginal: string;
  address: string;
  phone: string;
  website?: string;
  email?: string;
  /** Short official flag shown as a badge, e.g. "CSG certificate valid to 2028-11-23". */
  note?: string;
}

export interface RegistryMeta {
  country: string;
  asOf: string;
  source: string;
  sourceUrl: string;
  total: number;
  byCategory: Record<string, number>;
}

export interface RegistryConfig {
  slug: string;
  displayName: string;
  /** Short name of the list, used in headings: "the Ministry of Health list". */
  listName: string;
  regulator: string;
  /** "province" for Turkey, "region" for Korea (city or province). */
  regionNoun: string;
  /** What appearing on the list legally means, one or two sentences. */
  means: string;
  /** What it does not mean. */
  doesNotMean: string;
  /** Public lookup the reader should use to confirm a specific name. */
  lookup: { label: string; url: string };
  verifyGuideHref: string;
  /** Display order and labels for category slugs. */
  categories: { slug: string; label: string; blurb: string }[];
  /** Regions above this many rows split into per-category pages. */
  splitAbove: number;
  /** Category pages above this many rows split again into per-district pages. */
  districtSplitAbove: number;
  /** Dossier source id for the registry, so the hub can cite it. */
  sourceId: string;
}

export interface Registry {
  config: RegistryConfig;
  meta: RegistryMeta;
  rows: RegistryRow[];
}

